<?php $action=$custody?'/employee-custodies/'.$custody['id'].'/edit':'/employee-custodies';?><div class='page-header mb-3'><h2 class='page-title'><?=e($title)?></h2></div><form class='card' method='post' action='<?=e($action)?>'><div class='card-body'><input type='hidden' name='_token' value='<?=e($csrfToken)?>'><div class='row'><div class='col-md-6'><label class='form-label'>الموظف</label><select class='form-select js-tom-select' name='employee_id' required><option value=''>اختر الموظف</option><?php foreach($employees as$e):?><option value='<?=e($e['id'])?>' <?=($custody['employee_id']??null)==$e['id']?'selected':''?>><?=e($e['employee_code'].' - '.$e['name'])?></option><?php endforeach;?></select></div><div class='col-md-6'><label class='form-label'>المشروع</label><select class='form-select js-tom-select' name='project_id'><option value=''>بدون مشروع محدد</option><?php foreach($projects as$p):?><option value='<?=e($p['id'])?>' <?=($custody['project_id']??null)==$p['id']?'selected':''?>><?=e($p['project_code'].' - '.$p['name'])?></option><?php endforeach;?></select></div><div class='col-md-4'><label class='form-label'>تاريخ الإصدار</label><input class='form-control' type='date' name='issue_date' value='<?=e($custody['issue_date']??date('Y-m-d'))?>' required></div><div class='col-md-4'><label class='form-label'>المبلغ</label><input class='form-control' name='amount' value='<?=e($custody['amount']??'')?>' inputmode='decimal' required></div><div class='col-md-4'><label class='form-label'>نوع التمويل</label><select class='form-select' name='funding_type'><option value='cash'>نقدي</option><option value='bank' <?=($custody['funding_type']??'')==='bank'?'selected':''?>>بنك</option></select></div><div class='col-md-6'><label class='form-label'>حساب التمويل</label><select class='form-select' name='funding_account_id' required><?php foreach($funding_accounts as$a):?><option value='<?=e($a['id'])?>' <?=($custody['funding_account_id']??null)==$a['id']?'selected':''?>><?=e($a['account_code'].' - '.$a['name_ar'])?></option><?php endforeach;?></select></div><div class='col-md-6'><label class='form-label'>الغرض</label><input class='form-control' name='purpose' value='<?=e($custody['purpose']??'')?>'></div></div></div><div class='card-footer'><button class='btn btn-primary'>حفظ المسودة</button></div></form>
